        agentExecutor,
        agentRunnerService,
        commandRunner,
        localGitService,
        publisher: (event) => events.push(event),
    });
    run.start((completion) => completion);

    return { actionWorktreeRunService, agentRunnerService, commandRunner, events, run, localGitService };
}

